  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    segs = []
    for seg in segments:
        if not all(k in seg for k in ('name','importance','minimum','capacity')):
            raise ValueError('segment missing required field')
        try:
            name = str(seg['name'])
            importance = int(seg['importance'])
            minimum = int(seg['minimum'])
            capacity = int(seg['capacity'])
        except (ValueError, TypeError):
            raise ValueError('segment fields must be numeric')
        if minimum < 0 or capacity < minimum:
            raise ValueError('invalid minimum/capacity')
        segs.append({'name': name, 'importance': importance, 'min': minimum, 'cap': capacity, 'idx': len(segs)})
    sum_min = sum(s['min'] for s in segs)
    sum_cap = sum(s['cap'] for s in segs)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('budget out of feasible range')
    alloc = [s['min'] for s in segs]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segs):
            if alloc[i] >= s['cap']:
                continue
            score = s['importance'] / (alloc[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            raise ValueError('cannot allocate remaining budget')
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {}
    for s, a in zip(segs, alloc):
        by_name[s['name']] = a
    total = sum(alloc)
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
